import { AbstractPropertiesService, PropertyType, RefreshMode } from '@node-projects/web-component-designer';
import { ZplText } from '../widgets/zpl-text.js';
export class ZplTextPropertiesService extends AbstractPropertiesService {
    name = 'zplText';
    getRefreshMode() {
        return RefreshMode.fullOnValueChange;
    }
    isHandledElement(designItem) {
        return designItem.element instanceof ZplText;
    }
    _notifyChangedProperty(designItem) {
        designItem.element.refreshFromAttributes();
    }
    async getProperties() {
        const definitions = [
            { name: 'content', type: 'string', attributeName: 'content' },
            { name: 'fontName', displayName: 'font', type: 'enum', attributeName: 'font-name', enumValues: [...'0ABCDEFGH'].map(value => [value, value]) },
            { name: 'fontHeight', displayName: 'font height', type: 'number', attributeName: 'font-height', min: 1, max: 32000, step: 1 },
            { name: 'fontWidth', displayName: 'font width (0 = automatic)', description: 'Zero is Zebra automatic width; the selection rectangle still uses the measured printed width.', type: 'number', attributeName: 'font-width', min: 0, max: 32000, step: 1 },
            { name: 'rotation', type: 'enum', attributeName: 'rotation', enumValues: ['N', 'R', 'I', 'B'].map(value => [value, value]) }
        ];
        return definitions.map(property => ({ ...property, service: this, propertyType: PropertyType.attribute }));
    }
}
